%%\ IMAGE PROCESSING MINI-LAB  -  Version 1.5
% An interactive MATLAB script for exploring basic image processing.
%
% What it does:
%   1. Lets you pick a .jpg / .jpeg / .png image
%   2. Shows the original and a grayscale version
%   3. Splits the image into Red, Green and Blue channels
%   4. Plots pixel-intensity histograms
%   5. Detects edges (Canny, with Sobel for comparison)
%   6. Adjusts brightness / contrast (manual and automatic)
%   7. Blurs and sharpens the image
%   8. Lets you choose any result, compare it with the original,
%      and save it to the results/ folder
%
% Requires: MATLAB + Image Processing Toolbox.
% How to run: open this file and press the Run button (run the WHOLE file;
% the helper function at the bottom is only available when the full file runs).
%
% Version history
%   1.1  File selection, error handling, original + grayscale
%   1.2  RGB channels and histograms
%   1.3  Canny edge detection, brightness/contrast, auto contrast stretch
%   1.4  Blur, sharpen, result menu, comparison, saving
%   1.5  Settings block, repeatable choose/compare/save loop, cleaner saving

clear;      % remove old variables from the workspace
clc;        % clear the Command Window
close all;  % close any figures left open from a previous run

%%\ SETTINGS  (change these values to customize the program)
% Display
maximizeBigFigures = true;    % true = multi-panel figures open maximized so titles don't overlap
askForAdjustments  = true;    % true = show input dialogs; false = silently use the defaults below

% Brightness / contrast defaults (Section 10)
defaultBrightness = 30;       % -100 to 100, 0 = no change
defaultContrast   = 1.3;      % 0.5 to 2.0,  1 = no change

% Blur / sharpen defaults (Section 11)
defaultBlurSigma     = 2;     % 0.5 to 10, bigger = blurrier
defaultSharpenAmount = 1.5;   % 0 to 3,    bigger = sharper
sharpenRadius        = 2;     % width of the sharpening effect (not asked in a dialog)

% Canny edge thresholds [low high], between 0 and 1 (Section 9)
cannySensitive = [0.04 0.10]; % low thresholds  -> many edges
cannyStrict    = [0.15 0.30]; % high thresholds -> only strong edges

% Folder names (relative to this script's folder)
sampleFolderName  = 'sample_images';
resultsFolderName = 'results';

% Turn the true/false setting above into the value MATLAB's figure() expects.
if maximizeBigFigures
    bigFigureState = 'maximized';
else
    bigFigureState = 'normal';
end

%%\ SECTION 0: Check that the Image Processing Toolbox is available
% license('test', ...) returns 1 (true) if the toolbox license is available.
if ~license('test', 'Image_Toolbox')
    errordlg('This project needs the Image Processing Toolbox.', 'Missing toolbox');
    return;   % stop the script
end

%%\ SECTION 1: Let the user choose an image
% Open the file dialog in the sample_images folder next to this script.
% If that folder does not exist, fall back to the current folder.
scriptFolder = fileparts(mfilename('fullpath'));
startFolder  = fullfile(scriptFolder, sampleFolderName);
if ~isfolder(startFolder)
    startFolder = pwd;
end

% The filter's first column is the pattern, the second is the label shown.
fileFilter = {'*.jpg;*.jpeg;*.png', 'Image files (*.jpg, *.jpeg, *.png)'};

% uigetfile returns the file name and its folder, or 0 if the user cancels.
[fileName, filePath] = uigetfile(fileFilter, 'Select an image', [startFolder filesep]);

% ERROR HANDLING: user cancelled
if isequal(fileName, 0)
    disp('No file selected. Exiting the Mini-Lab.');
    return;
end

%%\ SECTION 2: Check the file type
% The dialog filter is only a convenience: a user can still type any file
% name, so we double-check the extension ourselves.
[~, baseName, fileExt] = fileparts(fileName);   % ~ means "ignore this output"
fileExt = lower(fileExt);                       % so .PNG and .png both work

allowedExtensions = {'.jpg', '.jpeg', '.png'};

% ERROR HANDLING: unsupported file type
if ~ismember(fileExt, allowedExtensions)
    errordlg(sprintf('"%s" is not supported. Please choose a .jpg, .jpeg or .png file.', fileName), ...
             'Unsupported file type');
    return;
end

%%\ SECTION 3: Load the image
fullFileName = fullfile(filePath, fileName);   % builds a path with the right slashes

% ERROR HANDLING: file is corrupted / unreadable
% Code in "try" runs normally; if MATLAB throws an error, it jumps to
% "catch" and stores the error details in ME instead of crashing.
try
    [originalImg, colorMap] = imread(fullFileName);

    % Some PNGs are "indexed" (pixels point into a color table).
    % Convert those to normal RGB so the rest of the code stays simple.
    if ~isempty(colorMap)
        originalImg = ind2rgb(originalImg, colorMap);
    end

    % Force uint8 (whole numbers 0-255). This also handles 16-bit PNGs, so
    % every later step can assume the same data type.
    originalImg = im2uint8(originalImg);
catch ME
    errordlg(sprintf('Could not read "%s".\n\n%s', fileName, ME.message), 'Read error');
    return;
end

%%\ SECTION 4: Look at what we loaded
% size() gives [rows, columns, channels]. A color image has 3 channels
% (R, G, B); a grayscale image has 1.
[numRows, numCols, numChannels] = size(originalImg);

fprintf('Loaded: %s\n', fileName); %[output:5d29ec81]
fprintf('Size:   %d rows x %d columns, %d channel(s)\n', numRows, numCols, numChannels); %[output:858024c3]
fprintf('Type:   %s\n', class(originalImg)); %[output:41cf0746]

% ERROR HANDLING: unusual channel counts (e.g. CMYK JPEGs have 4)
if numChannels ~= 1 && numChannels ~= 3
    errordlg('This image has an unusual number of color channels and is not supported.', ...
             'Unsupported image');
    return;
end

isColor = (numChannels == 3);   % true/false flag reused in later sections

%%\ SECTION 5: Display the original image
figure('Name', 'Original Image'); %[output:4a44b0b8]
imshow(originalImg); %[output:4a44b0b8]
% 'Interpreter','none' stops MATLAB from treating _ in file names as subscripts.
title(['Original Image: ' fileName], 'Interpreter', 'none'); %[output:4a44b0b8]

%%\ SECTION 6: Convert to grayscale and display
if isColor
    % rgb2gray uses a weighted sum:  gray = 0.2989*R + 0.5870*G + 0.1140*B
    % Green gets the biggest weight because human eyes are most sensitive to it.
    grayImg = rgb2gray(originalImg);
else
    grayImg = originalImg;   % already gray, nothing to convert
    disp('Note: the image was already grayscale.');
end

figure('Name', 'Grayscale Image'); %[output:9bf8fa89]
imshow(grayImg); %[output:9bf8fa89]
title('Grayscale Image'); %[output:9bf8fa89]

%%\ SECTION 7: Analyze the Red, Green and Blue channels separately
% A color image is three stacked matrices (layers): R, G, B.
% originalImg(:,:,1) means: ALL rows, ALL columns, layer number 1.
if isColor %[output:group:0c903743]
    redChannel   = originalImg(:,:,1);
    greenChannel = originalImg(:,:,2);
    blueChannel  = originalImg(:,:,3);

    % To show a channel "in color", rebuild a 3-layer image where the other
    % two layers are all zeros (black).
    zeroLayer = zeros(numRows, numCols, 'uint8');

    % cat(3, A, B, C) stacks matrices along the 3rd dimension (layers).
    redTinted   = cat(3, redChannel,  zeroLayer,    zeroLayer);
    greenTinted = cat(3, zeroLayer,   greenChannel, zeroLayer);
    blueTinted  = cat(3, zeroLayer,   zeroLayer,    blueChannel);

    figure('Name', 'RGB Channels', 'WindowState', bigFigureState); %[output:8c640b62]

    % Top row: each channel as a gray image (bright = that color is strong).
    subplot(2, 3, 1); imshow(redChannel);   title('Red channel'); %[output:8c640b62]
    subplot(2, 3, 2); imshow(greenChannel); title('Green channel'); %[output:8c640b62]
    subplot(2, 3, 3); imshow(blueChannel);  title('Blue channel'); %[output:8c640b62]

    % Bottom row: the same channels shown in their own color.
    subplot(2, 3, 4); imshow(redTinted);    title('Red only'); %[output:8c640b62]
    subplot(2, 3, 5); imshow(greenTinted);  title('Green only'); %[output:8c640b62]
    subplot(2, 3, 6); imshow(blueTinted);   title('Blue only'); %[output:8c640b62]

    % Average brightness of each channel. The (:) flattens a matrix into one
    % long column so mean() averages every pixel at once.
    fprintf('\nAverage channel intensity (0-255):\n'); %[output:23690b7d]
    fprintf('  Red:   %.1f\n', mean(redChannel(:))); %[output:120552b5]
    fprintf('  Green: %.1f\n', mean(greenChannel(:))); %[output:5cf9c321]
    fprintf('  Blue:  %.1f\n', mean(blueChannel(:))); %[output:87054456]
else
    disp('Skipping RGB channel analysis: the image is grayscale.');
end %[output:group:0c903743]

%%\ SECTION 8: Pixel-intensity histograms
% A histogram counts how many pixels have each brightness value (0-255).
%   x-axis: intensity (0 = black, 255 = white)
%   y-axis: number of pixels with that intensity
% Peaks on the left = dark image, on the right = bright image,
% narrow peak = low contrast, wide spread = high contrast.

% --- 8a: Grayscale histogram (plus R, G, B histograms for color images)
figure('Name', 'Pixel Intensity Histograms'); %[output:293f7f16]

if isColor %[output:group:63392c61]
    % imhist(I) draws the 256-bin histogram of image I in the current axes.
    subplot(2, 2, 1); imhist(grayImg); title('Grayscale histogram'); %[output:293f7f16]

    % [counts, binLocations] = imhist(I) returns the numbers instead of
    % drawing, so we can choose the colors ourselves with bar().
    [redCounts,   binLocations] = imhist(redChannel);
    [greenCounts, ~]            = imhist(greenChannel);
    [blueCounts,  ~]            = imhist(blueChannel);

    subplot(2, 2, 2); %[output:293f7f16]
    bar(binLocations, redCounts, 1, 'FaceColor', 'r', 'EdgeColor', 'none'); %[output:293f7f16]
    xlim([0 255]); title('Red histogram'); %[output:293f7f16]

    subplot(2, 2, 3); %[output:293f7f16]
    bar(binLocations, greenCounts, 1, 'FaceColor', 'g', 'EdgeColor', 'none'); %[output:293f7f16]
    xlim([0 255]); title('Green histogram'); %[output:293f7f16]

    subplot(2, 2, 4); %[output:293f7f16]
    bar(binLocations, blueCounts, 1, 'FaceColor', 'b', 'EdgeColor', 'none'); %[output:293f7f16]
    xlim([0 255]); title('Blue histogram'); %[output:293f7f16]

    % --- 8b: All three channels on one plot to compare color balance
    figure('Name', 'Combined RGB Histogram'); %[output:134d3e9b]
    plot(binLocations, redCounts,   'r', 'LineWidth', 1.5); hold on; %[output:134d3e9b]
    plot(binLocations, greenCounts, 'g', 'LineWidth', 1.5); %[output:134d3e9b]
    plot(binLocations, blueCounts,  'b', 'LineWidth', 1.5); %[output:134d3e9b]
    hold off;                      % stop adding to this plot %[output:134d3e9b]
    xlim([0 255]); %[output:134d3e9b]
    xlabel('Pixel intensity (0-255)'); %[output:134d3e9b]
    ylabel('Number of pixels'); %[output:134d3e9b]
    legend('Red', 'Green', 'Blue'); %[output:134d3e9b]
    title('Combined RGB histogram'); %[output:134d3e9b]
else
    imhist(grayImg);
    title('Grayscale histogram');
end %[output:group:63392c61]

% Quick numeric summary of the grayscale image.
% std() needs decimal numbers, so convert with double() first.
fprintf('\nGrayscale statistics:\n'); %[output:01718f8a]
fprintf('  Darkest pixel:   %d\n', min(grayImg(:))); %[output:190af081]
fprintf('  Brightest pixel: %d\n', max(grayImg(:))); %[output:54f23c07]
fprintf('  Average:         %.1f\n', mean(grayImg(:))); %[output:97e823d0]
fprintf('  Spread (std):    %.1f\n', std(double(grayImg(:)))); %[output:3b73c655]

%%\ SECTION 9: Edge detection (Canny)
% An "edge" is a place where brightness changes sharply, like an object's
% outline. Edge detectors work on a single-channel image, so we use grayImg.
%
% Canny's four steps:
%   1. Blur slightly (Gaussian) to reduce noise.
%   2. Measure the gradient: how fast brightness changes at each pixel.
%   3. Thin the edges to one pixel wide.
%   4. Hysteresis thresholding with two thresholds [low high]:
%        above HIGH -> definitely an edge
%        below LOW  -> definitely not an edge
%        in between -> kept only if connected to a definite edge
% Higher thresholds = fewer edges.

% With no thresholds given, edge() picks them automatically. The result is a
% LOGICAL image: 1 (white) = edge pixel, 0 (black) = no edge.
edgesAuto      = edge(grayImg, 'canny');
edgesSensitive = edge(grayImg, 'canny', cannySensitive);   % thresholds from SETTINGS
edgesStrict    = edge(grayImg, 'canny', cannyStrict);

% Sobel is a simpler detector (no blur/thinning). Shown for comparison.
edgesSobel = edge(grayImg, 'sobel');

figure('Name', 'Edge Detection', 'WindowState', bigFigureState); %[output:7855d28e]
% A cell array of text, {'line 1', 'line 2'}, makes a two-line title.
subplot(2, 2, 1); imshow(edgesAuto);      title({'Canny', '(automatic thresholds)'}); %[output:7855d28e]
subplot(2, 2, 2); imshow(edgesSobel);     title({'Sobel', '(for comparison)'}); %[output:7855d28e]
subplot(2, 2, 3); imshow(edgesSensitive); title({'Canny: low thresholds', '(sensitive)'}); %[output:7855d28e]
subplot(2, 2, 4); imshow(edgesStrict);    title({'Canny: high thresholds', '(strict)'}); %[output:7855d28e]

% nnz() counts non-zero elements (edge pixels); numel() counts all pixels.
fprintf('\nEdge pixels (percent of image):\n'); %[output:3b58a8b5]
fprintf('  Canny automatic: %.2f%%\n', 100 * nnz(edgesAuto)      / numel(edgesAuto)); %[output:50bb6c3e]
fprintf('  Canny sensitive: %.2f%%\n', 100 * nnz(edgesSensitive) / numel(edgesSensitive)); %[output:30b3a45b]
fprintf('  Canny strict:    %.2f%%\n', 100 * nnz(edgesStrict)    / numel(edgesStrict)); %[output:67a0bab9]
fprintf('  Sobel:           %.2f%%\n', 100 * nnz(edgesSobel)     / numel(edgesSobel)); %[output:60863a76]

%%\ SECTION 10: Brightness and contrast adjustment
% Brightness = make everything lighter or darker (add/subtract a number).
% Contrast   = push dark pixels darker and bright pixels brighter.
%
% Formula applied to every pixel value:
%   new = (old - 128) * contrastFactor + 128 + brightnessShift
% 128 (mid-gray) is the pivot, so contrast stretches the image around the
% middle instead of just making it brighter.

% --- 10a: Start from the defaults; optionally ask the user
brightnessShift = defaultBrightness;
contrastFactor  = defaultContrast;

if askForAdjustments
    prompt = {'Brightness shift (-100 to 100; 0 = no change):', ...
              'Contrast factor (0.5 to 2.0; 1 = no change):'};

    % inputdlg returns the answers as TEXT in a cell array, or {} on Cancel.
    % num2str turns our default numbers into text for the boxes.
    answer = inputdlg(prompt, 'Brightness / Contrast', [1 50], ...
                      {num2str(defaultBrightness), num2str(defaultContrast)});

    % ERROR HANDLING: cancelled or invalid input
    if isempty(answer)
        disp('Brightness/contrast dialog cancelled - using default values.');
    else
        % str2double converts text to a number (NaN if it is not a number).
        newBrightness = str2double(answer{1});
        newContrast   = str2double(answer{2});

        if isnan(newBrightness) || isnan(newContrast)
            warndlg('Please enter numbers only. Using default values instead.', 'Invalid input');
        else
            % Clamp into the allowed range: min() caps the top, max() the bottom.
            brightnessShift = max(-100, min(100, newBrightness));
            contrastFactor  = max(0.5,  min(2.0, newContrast));
        end
    end
end
fprintf('\nUsing brightness shift = %.1f, contrast factor = %.2f\n', brightnessShift, contrastFactor); %[output:6204965b]

% --- 10b: Apply the adjustment
% Convert to double first: a uint8 cannot hold negatives or values above
% 255, so (old - 128) would be clipped too early. Converting back with
% uint8() rounds and clips to 0-255 ("saturation").
adjustedImg = uint8((double(originalImg) - 128) * contrastFactor + 128 + brightnessShift);

% Grayscale copy of the adjusted image, only used to plot its histogram.
if isColor
    adjustedGray = rgb2gray(adjustedImg);
else
    adjustedGray = adjustedImg;
end

figure('Name', 'Brightness / Contrast Adjustment'); %[output:2ec572ff]
subplot(2, 2, 1); imshow(originalImg);  title('Original'); %[output:2ec572ff]
subplot(2, 2, 2); imshow(adjustedImg);  title('Adjusted'); %[output:2ec572ff]
subplot(2, 2, 3); imhist(grayImg);      title('Original histogram'); %[output:2ec572ff]
subplot(2, 2, 4); imhist(adjustedGray); title('Adjusted histogram'); %[output:2ec572ff]

fprintf('Average brightness: %.1f (original)  ->  %.1f (adjusted)\n', ... %[output:group:0f2cadd0] %[output:663cee74]
        mean(grayImg(:)), mean(adjustedGray(:))); %[output:group:0f2cadd0] %[output:663cee74]

% --- 10c: Automatic contrast stretch with imadjust
% stretchlim(I) finds the intensity range holding most pixels (ignoring the
% darkest and brightest 1%), as FRACTIONS between 0 and 1.
% imadjust(I, [low high], []) maps "low" to black and "high" to white and
% stretches everything in between. The empty [] means [0 1].
stretchRange  = stretchlim(grayImg);
stretchedGray = imadjust(grayImg, stretchRange, []);

fprintf('Auto stretch range: %.0f to %.0f (out of 0-255)\n', ... %[output:group:56d17ca7] %[output:3d3031d4]
        stretchRange(1) * 255, stretchRange(2) * 255); %[output:group:56d17ca7] %[output:3d3031d4]

figure('Name', 'Automatic Contrast Stretch'); %[output:73f0890b]
subplot(2, 2, 1); imshow(grayImg);       title('Grayscale'); %[output:73f0890b]
subplot(2, 2, 2); imshow(stretchedGray); title('After imadjust + stretchlim'); %[output:73f0890b]
subplot(2, 2, 3); imhist(grayImg);       title('Before'); %[output:73f0890b]
subplot(2, 2, 4); imhist(stretchedGray); title('After'); %[output:73f0890b]

%%\ SECTION 11: Blur and sharpen
% BLUR averages each pixel with its neighbors, smoothing the image and
% hiding noise. A Gaussian blur weights close neighbors more than distant
% ones; "sigma" sets how far it reaches.
%
% SHARPEN boosts detail at edges using "unsharp masking":
%     sharpened = original + amount * (original - blurred)
% (original - blurred) isolates fine detail; adding it back makes edges crisper.

% --- 11a: Start from the defaults; optionally ask the user
blurSigma     = defaultBlurSigma;
sharpenAmount = defaultSharpenAmount;

if askForAdjustments
    blurPrompt = {'Blur strength / sigma (0.5 to 10):', ...
                  'Sharpen amount (0 to 3):'};
    blurAnswer = inputdlg(blurPrompt, 'Blur and Sharpen', [1 50], ...
                          {num2str(defaultBlurSigma), num2str(defaultSharpenAmount)});

    % ERROR HANDLING: cancelled or invalid input
    if isempty(blurAnswer)
        disp('Blur/sharpen dialog cancelled - using default values.');
    else
        newSigma  = str2double(blurAnswer{1});
        newAmount = str2double(blurAnswer{2});
        if isnan(newSigma) || isnan(newAmount)
            warndlg('Please enter numbers only. Using default values instead.', 'Invalid input');
        else
            blurSigma     = max(0.5, min(10, newSigma));
            sharpenAmount = max(0,   min(3,  newAmount));
        end
    end
end
fprintf('\nUsing blur sigma = %.1f, sharpen amount = %.2f\n', blurSigma, sharpenAmount); %[output:9bba916e]

% --- 11b: Apply the filters to the ORIGINAL image
% imgaussfilt blurs each color layer separately and keeps the uint8 type.
blurredImg = imgaussfilt(originalImg, blurSigma);

% imsharpen takes 'Name', value option pairs. For color images it sharpens
% only the brightness information, so colors do not shift.
sharpenedImg = imsharpen(originalImg, 'Radius', sharpenRadius, 'Amount', sharpenAmount);

% --- 11c: Show full images (top row) and a zoomed center crop (bottom row)
% Sharpening is hard to see on a full image, so we also crop the center.
% A(rowRange, colRange, :) selects a rectangle; ":" keeps all color layers.
cropRows = max(1, round(numRows / 3)) : round(2 * numRows / 3);
cropCols = max(1, round(numCols / 3)) : round(2 * numCols / 3);

figure('Name', 'Blur and Sharpen', 'WindowState', bigFigureState); %[output:4ecd3d7d]
subplot(2, 3, 1); imshow(originalImg);  title('Original'); %[output:4ecd3d7d]
subplot(2, 3, 2); imshow(blurredImg);   title({'Blurred', sprintf('(sigma = %.1f)', blurSigma)}); %[output:4ecd3d7d]
subplot(2, 3, 3); imshow(sharpenedImg); title({'Sharpened', sprintf('(amount = %.1f)', sharpenAmount)}); %[output:4ecd3d7d]
subplot(2, 3, 4); imshow(originalImg(cropRows, cropCols, :));  title('Original (zoom)'); %[output:4ecd3d7d]
subplot(2, 3, 5); imshow(blurredImg(cropRows, cropCols, :));   title('Blurred (zoom)'); %[output:4ecd3d7d]
subplot(2, 3, 6); imshow(sharpenedImg(cropRows, cropCols, :)); title('Sharpened (zoom)'); %[output:4ecd3d7d]

%%\ SECTION 12: Choose a result, compare it with the original, and save it
% This section repeats until the user is done, so several results can be
% compared and saved in one run.

% Put every result in a "cell array": curly braces { } make a list that can
% hold different kinds of images. Read item k with resultImages{k}.
resultNames  = {'Grayscale', ...
                'Canny edges (automatic)', ...
                'Brightness/contrast adjusted', ...
                'Auto contrast stretch (grayscale)', ...
                'Blurred (Gaussian)', ...
                'Sharpened'};
resultTags   = {'gray', 'edges', 'adjusted', 'stretched', 'blurred', 'sharpened'};  % used in file names
resultImages = {grayImg, edgesAuto, adjustedImg, stretchedGray, blurredImg, sharpenedImg};

resultsFolder = fullfile(scriptFolder, resultsFolderName);
savedFiles    = {};     % will collect the path of every image we save

% "while true" loops forever; "break" is how we leave it.
while true %[output:group:9aa72b2f]

    % --- 12a: Choose a result
    % listdlg returns the chosen position and a true/false flag that is
    % false if the user pressed Cancel or closed the window.
    [choiceIndex, madeChoice] = listdlg( ...
        'ListString',    resultNames, ...
        'SelectionMode', 'single', ...
        'Name',          'Choose a result', ...
        'PromptString',  'Which processed image do you want to compare and save?', ...
        'ListSize',      [340 130]);

    if ~madeChoice
        disp('No result selected. Leaving the result menu.');
        break;
    end

    selectedImg  = resultImages{choiceIndex};   % curly braces: get the image itself
    selectedName = resultNames{choiceIndex};
    selectedTag  = resultTags{choiceIndex};

    % The edge map is "logical" (true/false). Convert it to uint8 so it is
    % 0 (black) / 255 (white), like every other image, and saves the same way.
    if islogical(selectedImg)
        selectedImg = im2uint8(selectedImg);
    end
    fprintf('\nYou selected: %s\n', selectedName); %[output:199c8f6b]

    % --- 12b: Side-by-side comparison
    % figure(100) always means "figure number 100", so each pass REUSES the
    % same window; clf clears it first.
    compareFig = figure(100); %[output:4120f4d3]
    clf(compareFig); %[output:4120f4d3]
    set(compareFig, 'Name', 'Original vs Processed', 'NumberTitle', 'off', ...
                    'WindowState', bigFigureState);

    ax1 = subplot(1, 2, 1); imshow(originalImg);  title('Original');
    ax2 = subplot(1, 2, 2); imshow(selectedImg);  title(selectedName);

    % linkaxes makes both axes zoom and pan together, so you can inspect the
    % same spot in both images.
    linkaxes([ax1 ax2]);
    sgtitle(['Comparison: Original vs. ' selectedName]);
    drawnow;   % make sure the figure is drawn before the Save dialog appears

    % --- 12c: Save (the work is done in the helper function at the bottom)
    savedPath = saveProcessedImage(selectedImg, [baseName '_' selectedTag '.png'], resultsFolder);
    if ~isempty(savedPath)
        savedFiles{end+1} = savedPath;   % end+1 = "one position past the last item"
    end

    % --- 12d: Go again?
    again = questdlg('Compare or save another result?', 'Image Processing Mini-Lab', ...
                     'Yes', 'No', 'Yes');
    if ~strcmp(again, 'Yes')   % also true if the user closed the dialog
        break;
    end
end %[output:group:9aa72b2f]

%%\ SECTION 13: Summary
fprintf('\n=====================================================\n');
fprintf(' Image Processing Mini-Lab (v1.5) finished successfully.\n');
fprintf(' Image analyzed: %s\n', fileName);
if isempty(savedFiles)
    fprintf(' No images were saved.\n');
else
    fprintf(' %d image(s) saved:\n', numel(savedFiles));
    for k = 1:numel(savedFiles)
        fprintf('   %s\n', savedFiles{k});
    end
end
fprintf('=====================================================\n');

%%\ LOCAL FUNCTIONS
% In a script file, helper functions must come at the very END of the file.
% A function keeps a long job in one named, reusable place. Inside a
% function, "return" leaves only the function (in the main script, "return"
% would stop the whole program) - which is exactly what we want here.

function savedPath = saveProcessedImage(img, suggestedName, resultsFolder)
% SAVEPROCESSEDIMAGE  Ask where to save an image and write it to disk.
%   savedPath = saveProcessedImage(img, suggestedName, resultsFolder)
%   Returns the full path of the saved file, or '' if nothing was saved.

    savedPath = '';   % the answer if we leave early: "nothing saved"

    % ERROR HANDLING: make sure the results folder exists.
    if ~isfolder(resultsFolder)
        [folderOK, folderMsg] = mkdir(resultsFolder);   % folderOK is true/false
        if ~folderOK
            errordlg(sprintf('Could not create the results folder.\n\n%s', folderMsg), 'Save error');
            return;
        end
    end

    % uiputfile is the "Save as" dialog. Like uigetfile, it returns 0 on Cancel.
    saveFilter = {'*.png', 'PNG image (*.png)'; ...
                  '*.jpg', 'JPEG image (*.jpg)'};
    [saveName, saveFolder] = uiputfile(saveFilter, 'Save processed image', ...
                                       fullfile(resultsFolder, suggestedName));
    if isequal(saveName, 0)
        disp('Save cancelled. Nothing was saved.');
        return;
    end

    % If the user typed a name with no extension, default to PNG.
    [~, ~, saveExt] = fileparts(saveName);
    saveExt = lower(saveExt);
    if isempty(saveExt)
        saveName = [saveName '.png'];
        saveExt  = '.png';
    end

    % ERROR HANDLING: unsupported output format
    if ~ismember(saveExt, {'.png', '.jpg', '.jpeg'})
        errordlg('Please save as .png, .jpg or .jpeg.', 'Unsupported file type');
        return;
    end

    % ERROR HANDLING: writing can fail (full disk, no permission, ...)
    fullSavePath = fullfile(saveFolder, saveName);
    try
        % PNG is lossless; JPEG is smaller but loses a little quality.
        imwrite(img, fullSavePath);
    catch ME
        errordlg(sprintf('Could not save the image.\n\n%s', ME.message), 'Save error');
        return;
    end

    savedPath = fullSavePath;
    fprintf('Saved: %s\n', savedPath);
    msgbox(sprintf('Saved to:\n%s', savedPath), 'Image saved');
end

